.mgr-time-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.mgr-modal-card input[type="date"] {
  padding: 7px 10px;
  border: 1px solid #d1d8dd;
  border-radius: 6px;
  font-size: 13px;
  color: #36414c;
  background: #fff;
}

/* Outlet column tint */
.mgr-outlet-col[data-outlet="CFM West"] {
  background: #f3f8f0;
  border-color: #cfe0c4;
}
.mgr-outlet-col[data-outlet="CFM South"] {
  background: #f0f5fb;
  border-color: #c5d6ea;
}
.mgr-outlet-col[data-outlet="Events Outside Crafted"] {
  background: #faf5ff;
  border-color: #ddcceb;
}
.mgr-outlet-col[data-outlet="Wharehouse"],
.mgr-outlet-col[data-outlet="Warehouse"] {
  background: #fff8f0;
  border-color: #ecd9c3;
}
.mgr-outlet-col {
  text-align: center;
}
.mgr-shift, .employee-other {
  text-align: center;
}
.mgr-timeoff-bar {
  text-align: left;
}
.mgr-timeoff-text {
  text-align: center;
}

.mgr-my-star {
  color: #1f272e;
  font-size: 11px;
  line-height: 1;
}
.mgr-my-name {
  color: #1f272e;
  font-weight: 700;
}
.mgr-shift.mgr-shift-mine {
  box-shadow: 0 0 0 2px rgba(31, 39, 46, 0.35);
  font-weight: 600;
}
.mgr-dur {
  font-size: 10px;
  font-weight: 600;
  opacity: 0.85;
}

.mgr-open-shift {
  font-weight: 700;
  font-style: italic;
  opacity: 0.9;
}

.mgr-outlet-hours-label {
  font-size: 10px;
  font-weight: 600;
  color: #2c3338;
  text-align: center;
  margin: 0 0 4px;
}
.mgr-outlet-hours-label.is-closed {
  color: #98a1a9;
  font-weight: 500;
}
.mgr-timeline {
  position: relative;
  width: 100%;
  min-height: 48px;
  border-radius: 4px;
  background: repeating-linear-gradient(
    to bottom,
    rgba(0,0,0,0.03) 0,
    rgba(0,0,0,0.03) 1px,
    transparent 1px,
    transparent 18px
  );
  background-color: rgba(255,255,255,0.45);
  border: 1px dashed #d1d8dd;
  margin-bottom: 4px;
}
.mgr-timeline.is-closed {
  background: #f0f0f0;
  border-style: solid;
  opacity: 0.85;
}
.mgr-timeline .mgr-shift {
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2px 3px;
  font-size: 10px;
  line-height: 1.2;
}
.mgr-outlet-col.is-closed .mgr-outlet-col-title {
  opacity: 0.7;
}


.mgr-timeline .mgr-shift.mgr-shift-overlap {
  font-size: 10px;
  padding: 3px 4px;
  line-height: 1.25;
}

/* Past-shift lock (2026-11-09) */
.mgr-shift.mgr-shift-locked { filter: grayscale(85%); opacity: .6; }
.mgr-lock-note { margin: 6px 0 0; font-size: 13px; color: #8a6d3b; }
.mgr-modal select:disabled, .mgr-modal input:disabled { background: #f3f3f3; color: #666; }
